2. Logika Pengajuan Judul TA oleh Mahasiswa
export const handlePengajuanJudul = async (
 judul: string,
 bidang: string,
 dosen1Id: number | null,
 dosen2Id: number | null
) => {
 // Validasi 1: Memeriksa kelengkapan seluruh atribut wajib
 if (!judul.trim() || !bidang.trim() || !dosen1Id || !dosen2Id) {
 throw new Error('Judul, bidang penelitian, dan kedua dosen
pembimbing wajib dipilih.');
 }
 // Validasi 2: Memeriksa integritas penugasan dosen pembimbing
 if (dosen1Id === dosen2Id) {
 throw new Error('Dosen Pembimbing 1 dan Pembimbing 2 tidak boleh
orang yang sama.');
 }
 const payload = {
 judul: judul.trim(),
 bidang_penelitian: bidang.trim(),
 pembimbing_1: dosen1Id,
 pembimbing_2: dosen2Id,
 };
 const response = await pengajuanTAApi.create(payload);
 return response.data;
};
