4.3.3.1 Pengkodean
Pengkodean dilaksanakan menggunakan dengan framework React
Native dan Expo Router. Pada alur persetujuan dari dosen, fokus
implementasi terletak pada mekanisme dari dosen untuk menyetujui judul
dari mahasiswa yang telah mengajukan serta memberikan catatan bagi
mahasiswa.
1. Logika Persetujuan Judul Tugas Akhir oleh Dosen
export const executePersetujuanJudulTA = async (
 judulId: number,
 statusAksi: 'approved' | 'rejected',
 catatanPenolakan?: string
) => {
 // Validasi bisnis: Penolakan judul wajib menyertakan alasan
perbaikan
 if (statusAksi === 'rejected' && (!catatanPenolakan ||
!catatanPenolakan.trim())) {
 throw new Error('Alasan penolakan wajib diisi untuk memberikan
arahan revisi.');
 }
 const payload = {
 status: statusAksi === 'approved' ? 'Disetujui' : 'Ditolak',
 catatan: statusAksi === 'rejected' ? catatanPenolakan!.trim() :
'',
 };
 const response = await pengajuanTAApi.updateStatusJudul(judulId,
payload);
 return response.data;
};
