1. Logika Pengiriman Notifikasi
export const sendJudulApprovedPushNotification = async (
 expoPushToken: string | null,
 judulMahasiswa: string,
 judulId: number
) => {
 // Validasi 1: Memeriksa apakah token perangkat mahasiswa tersedia
 if (!expoPushToken || !expoPushToken.trim()) {
 console.warn('Mahasiswa belum memiliki push token terdaftar.');
 return { success: false, reason: 'NO_TOKEN' };
 }
 // Validasi 2: Memeriksa validitas format prefix token Expo
 if (!expoPushToken.startsWith('ExponentPushToken[') &&
 !expoPushToken.startsWith('ExpoPushToken[')) {
 console.error('Format Expo push token tidak valid:',
expoPushToken);
 return { success: false, reason: 'INVALID_TOKEN' };
 }
 // Penyiapan data payload dan pengiriman ke gateway Expo
 const payload: PushNotificationPayload = {
 to: expoPushToken,
 title: 'Judul Tugas Akhir Disetujui! 🎉',
 body: `Selamat! Usulan judul "${judulMahasiswa}" telah
disetujui.`,
 data: { screen: 'DetailJudul', judulId },
 sound: 'default',
 priority: 'high',
 };
 const response = await axios.post(
 'https://exp.host/--/api/v2/push/send',
 payload,
 { headers: { 'Content-Type': 'application/json' } }
 );
 return { success: true, ticket: response.data };
}
